# Die drei Kern-Ideen der Python-Lösung:

# 1. Funktionen als Wörterbuch-Werte:
OPERATIONEN = {'+': addiere, '-': subtrahiere, '/': dividiere}
ergebnis = OPERATIONEN[wahl](a, b)   # Aufruf über den Schlüssel

# 2. Sichere Zahleneingabe:
def zahl_einlesen(prompt):
    while True:
        try:
            return float(input(prompt))
        except ValueError:
            print("Bitte eine gültige Zahl eingeben!")

# 3. Fehler in den Verlauf statt Absturz:
try:
    ergebnis = OPERATIONEN[wahl](a, b)
    eintrag = f"{a:g} {wahl} {b:g} = {ergebnis:g}"
except ValueError as e:
    eintrag = f"{a:g} {wahl} {b:g} = Fehler: {e}"

